export default function Home(){
  const [menu,setMenu]=useState(false); const [filter,setFilter]=useState("Breloki"); const [keyringCollection,setKeyringCollection]=useState("Wszystkie breloki"); const [sent,setSent]=useState(false);
  const [showAllKeyrings,setShowAllKeyrings]=useState(false);
  const [chosenColors,setChosenColors]=useState<string[]>([]); const [briefMode,setBriefMode]=useState("Mam konkretny pomysł");
  const [gallery,setGallery]=useState<{title:string;type?:string;items:(typeof projects)[number][];active:number}|null>(null);
  const visible=useMemo(()=>{
    const byType=filter==="Wszystkie"?portfolioProjects:portfolioProjects.filter(p=>p.type===filter);
    const filtered=filter==="Breloki"
      ? keyringCollection==="Wszystkie breloki"
        ? byType.filter(p=>!("collection" in p))
        : byType.filter(p=>"collection" in p && p.collection===keyringCollection)
      : byType.filter(p=>p.type!=="Bransoletki" || p.src.includes("/bransoletki/2026/"));
    const crossbodyOrder=["/projects/crossbody/2026/21.png","/projects/crossbody/2026/22.png","/projects/crossbody/2026/23.png","/projects/crossbody/2026/24.png","/projects/crossbody/2026/25.png","/projects/crossbody/2026/26.png","/projects/crossbody/2026/27.png","/projects/crossbody/2026/28.png","/projects/crossbody/2026/29.png","/projects/crossbody/2026/05.png","/projects/crossbody/2026/14.png","/projects/crossbody/2026/01.png","/projects/crossbody/2026/04.png","/projects/crossbody/2026/15.png","/projects/crossbody/2026/12.png","/projects/crossbody/2026/06.png","/projects/crossbody/2026/08.png","/projects/crossbody/2026/10.png","/projects/crossbody/2026/18.png","/projects/crossbody/2026/19.png","/projects/crossbody/2026/11.png","/projects/crossbody/2026/02.png","/projects/crossbody/2026/17.png","/projects/crossbody/2026/13.png","/projects/crossbody/2026/20.png"];
    return [...filtered].sort((a,b)=>a.type==="Phone strapy crossbody" && b.type==="Phone strapy crossbody" ? ((crossbodyOrder.indexOf(a.src)+1||99)-(crossbodyOrder.indexOf(b.src)+1||99)) : a.type==="Breloki" && a.title==="CR7" ? 1 : b.type==="Breloki" && b.title==="CR7" ? -1 : 0).map(p=>p.src.includes("/phone-straps/2026/26.png")?{...p,title:"Green Kamp"}:p).map(p=>p.type==="Breloki" && /^\/projects\/breloki\/[^/]+$/.test(p.src)
      ? {...p,src:p.src.replace("/projects/breloki/","/projects/breloki/raw/")}
      : p);
  },[filter,keyringCollection]);
  const crossbodyGroups=useMemo(()=>{
    if(filter!=="Phone strapy crossbody")return [];
    return Object.entries(visible.reduce<Record<string,(typeof projects)[number][]>>((groups,project)=>{
      const name=project.title.split(" - ")[0];
      (groups[name]??=[]).push(project);
      return groups;
    },{}));
  },[filter,visible]);
  const displayedProjects=filter==="Breloki"&&!showAllKeyrings?visible.slice(0,6):visible;
  const matHandleItems=useMemo(()=>filter==="Inne"?visible.filter(project=>project.title.startsWith("Uchwyt na matę")):[],[filter,visible]);
  const colorPopItems=useMemo(()=>filter==="Inne"?visible.filter(project=>project.src.includes("/sznurki-do-okularow/kolorowy-")):[],[filter,visible]);
  const blackGreenItems=useMemo(()=>filter==="Inne"?visible.filter(project=>project.src.includes("/sznurki-do-okularow/czarny-")):[],[filter,visible]);
  const bagHandleItems=useMemo(()=>filter==="Inne"?visible.filter(project=>project.src.includes("/uchwyty-do-torby/orange-blue")):[],[filter,visible]);
  const necklaceItems=useMemo(()=>filter==="Inne"?visible.filter(project=>project.src.includes("/naszyjnik/summer-charms")):[],[filter,visible]);
  const petTagItems=useMemo(()=>filter==="Inne"?visible.filter(project=>project.src.includes("/adresowka-dla-pupila/")):[],[filter,visible]);
  useEffect(()=>{
    const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==="Escape")setGallery(null)};
    window.addEventListener("keydown",closeOnEscape);
    return()=>window.removeEventListener("keydown",closeOnEscape);
  },[]);
  const toggleColor=(c:string)=>setChosenColors(v=>v.includes(c)?v.filter(x=>x!==c):[...v,c]);
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setSent(true)};
  return <main>
    <header className="site-header"><a className="logo-link" href="#start" aria-label="Surfcraftstories - start"><img src="/surfcraftstories-logo.png" alt="Surfcraftstories" /></a><button className="menu-toggle" aria-expanded={menu} aria-controls="main-nav" onClick={()=>setMenu(!menu)}>{menu?"Zamknij":"Menu"}</button><nav id="main-nav" className={menu?"nav-open":""} onClick={()=>setMenu(false)}><a href="#realizacje">Realizacje</a><a href="#produkty">Co tworzę</a><a href="#cennik">Cennik</a><a href="#kolory">Kolory i detale</a><a href="#historia">Historia</a><a className="nav-cta" href="#zamowienie">Stwórzmy coś Twojego</a></nav></header>

    <section className="hero" id="start"><div className="hero-grid"><div className="hero-copy"><img className="hero-logo" src="/surfcraftstories-logo.png" alt="Logo Surfcraftstories: kolorowa fala upleciona z paracordu"/><p className="kicker">RĘCZNA PRACA / PARACORD / SURFSKATE</p><h1>Codzienne rzeczy.<br/><span>Niecodzienny</span><br/>charakter.</h1><p className="hero-lead">Surfcraftstories to ręcznie wyplatane akcesoria z paracordu - z zajawki do surfskate’u, miłości do koloru i potrzeby robienia rzeczy po swojemu.</p><div className="actions"><a className="btn btn-dark" href="#realizacje">Zobacz realizacje <b>↘</b></a><a className="btn btn-line" href="#zamowienie">Opowiedz mi o pomyśle</a></div><div className="hero-instagram"><span className="instagram-badge">BĄDŹ NA BIEŻĄCO!</span><span className="instagram-copy">Nowe realizacje, kolory i kulisy znajdziesz na Instagramie.</span><a href="https://www.instagram.com/surfcraftstories/" target="_blank" rel="noreferrer"><span>@surfcraftstories</span><b>ZAOBSERWUJ!</b><i>↗</i></a></div></div><div className="hero-visual"><img className="hero-product" src="/projects/kolorowe-trio.png" alt="Trzy kolorowe akcesoria Surfcraftstories wykonane z paracordu"/><div className="visual-label"><span>PRAWDZIWA REALIZACJA</span><b>01 / HERO</b></div><p>Kolor, materiał i detal.<br/>Każdy egzemplarz po swojemu.</p></div></div><div className="route"><span>POMYSŁ</span><i>→</i><span>KOLORY</span><i>→</i><span>SPLOT</span><i>→</i><span>DETAL</span><i>→</i><span>TWOJA HISTORIA</span></div></section>

    <section className="section projects" id="realizacje">
      <div className="section-top">
        <div><p className="index">01 / REALIZACJE</p><h2>Każdy splot<br/>zaczyna się <em>inaczej.</em></h2></div>
        <p className="section-intro">Od oszczędnej czerni i bieli po soczyste, wakacyjne miksy. Wybierz kategorię i zobacz, jak różne historie mogą zacząć się od kilku linek.</p>
      </div>
      <div className="filters" role="group" aria-label="Filtruj realizacje">
        {filters.map(f=><button key={f} className={filter===f?"active":""} onClick={()=>{setFilter(f);setShowAllKeyrings(false);if(f!=="Breloki")setKeyringCollection("Wszystkie breloki")}}>{f}</button>)}
      </div>
      {filter==="Breloki"&&<div className="subfilters" role="group" aria-label="Filtruj kolekcje breloków">
        <span>KOLEKCJE</span>
        {keyringCollections.map(c=><button key={c} className={keyringCollection===c?"active":""} onClick={()=>{setKeyringCollection(c);setShowAllKeyrings(false)}}>{c}</button>)}
      </div>}
      {filter==="Inne"&&petTagItems.length>0&&(()=>{const main=petTagItems[0];return <div className="project-grid pet-tag-gallery-grid"><article className="project-card pet-tag-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Adresówka dla pupila",type:"Adresówka dla pupila",items:petTagItems,active:0})} aria-label="Otwórz galerię: Adresówka dla pupila"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{petTagItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Adresówka dla pupila</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia adresówki dla pupila">{petTagItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Adresówka dla pupila",type:"Adresówka dla pupila",items:petTagItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Inne"&&matHandleItems.length>0&&(()=>{const main=matHandleItems[0];return <div className="project-grid mat-gallery-grid mat-gallery-first"><article className="project-card mat-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Uchwyt na matę",type:"Uchwyt na matę",items:matHandleItems,active:0})} aria-label="Otwórz galerię: Uchwyt na matę"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{matHandleItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Uchwyt na matę</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia uchwytu na matę">{matHandleItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Uchwyt na matę",type:"Uchwyt na matę",items:matHandleItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Inne"&&bagHandleItems.length>0&&(()=>{const main=bagHandleItems[0];return <div className="project-grid bag-handle-gallery-grid"><article className="project-card bag-handle-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Uchwyt do torby - Orange Blue",type:"Uchwyt do torby",items:bagHandleItems,active:0})} aria-label="Otwórz galerię: Uchwyt do torby Orange Blue"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{bagHandleItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Uchwyt do torby<br/>Orange Blue</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia uchwytu do torby">{bagHandleItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Uchwyt do torby - Orange Blue",type:"Uchwyt do torby",items:bagHandleItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Inne"&&necklaceItems.length>0&&(()=>{const main=necklaceItems[0];return <div className="project-grid necklace-gallery-grid"><article className="project-card necklace-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Naszyjnik - Summer Charms",type:"Naszyjnik",items:necklaceItems,active:0})} aria-label="Otwórz galerię: Naszyjnik Summer Charms"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{necklaceItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Naszyjnik<br/>Summer Charms</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia naszyjnika">{necklaceItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Naszyjnik - Summer Charms",type:"Naszyjnik",items:necklaceItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Inne"&&blackGreenItems.length>0&&(()=>{const main=blackGreenItems[0];return <div className="project-grid black-green-gallery-grid"><article className="project-card black-green-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Sznurek do okularów - Black Green",type:"Sznurek do okularów",items:blackGreenItems,active:0})} aria-label="Otwórz galerię: Sznurek do okularów Black Green"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{blackGreenItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Sznurek do okularów<br/>Black Green</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia sznurka do okularów Black Green">{blackGreenItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Sznurek do okularów - Black Green",type:"Sznurek do okularów",items:blackGreenItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Inne"&&colorPopItems.length>0&&(()=>{const main=colorPopItems[0];return <div className="project-grid color-pop-gallery-grid"><article className="project-card color-pop-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Sznurek do okularów - Color Pop",type:"Sznurek do okularów",items:colorPopItems,active:0})} aria-label="Otwórz galerię: Sznurek do okularów Color Pop"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{colorPopItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Sznurek do okularów<br/>Color Pop</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia sznurka do okularów Color Pop">{colorPopItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Sznurek do okularów - Color Pop",type:"Sznurek do okularów",items:colorPopItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Inne"&&matHandleItems.length>0&&(()=>{const main=matHandleItems[0];return <div className="project-grid mat-gallery-grid"><article className="project-card mat-gallery-card"><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title:"Uchwyt na matę",type:"Uchwyt na matę",items:matHandleItems,active:0})} aria-label="Otwórz galerię: Uchwyt na matę"><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{matHandleItems.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Inne</small><h3>Uchwyt na matę</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label="Pozostałe ujęcia uchwytu na matę">{matHandleItems.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title:"Uchwyt na matę",type:"Uchwyt na matę",items:matHandleItems,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article></div>})()}
      {filter==="Phone strapy crossbody"&&<div className="project-grid crossbody-gallery-grid">{crossbodyGroups.map(([title,items])=>{const main=items[0];return <article className="project-card crossbody-card" key={title}><button className={`project-image gallery-main ${main.tone}`} type="button" onClick={()=>setGallery({title,items,active:0})} aria-label={`Otwórz galerię: ${title}`}><img src={main.src} alt={main.alt} loading="lazy"/><span className="project-id">{items.length} UJĘCIA</span><span className="gallery-open">Zobacz galerię ↗</span></button><div className="project-meta"><div><small>Phone strap crossbody</small><h3>{title}</h3><p>{main.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{main.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div><div className="gallery-thumbnails" aria-label={`Pozostałe ujęcia: ${title}`}>{items.map((item,index)=><button type="button" key={item.id} onClick={()=>setGallery({title,items,active:index})} aria-label={`Otwórz zdjęcie ${index+1}: ${item.title}`}><img src={item.src} alt="" loading="lazy"/></button>)}</div></article>})}</div>}
      <div className={filter==="Phone strapy crossbody"?"crossbody-original-hidden":""}><div className="project-grid">{visible.length===0?<div className="empty-category"><b>SEKCJA GOTOWA</b><h3>Pierwsze realizacje pojawią się tutaj.</h3><p>Kategoria jest przygotowana na zdjęcia, kolory i opis personalizacji - bez wymyślania produktów, których jeszcze nie pokazałaś.</p></div>:displayedProjects.map(p=><article className="project-card" key={p.id}><div className={`project-image ${p.tone} ${"fit" in p ? p.fit : ""} ${p.type==="Phone strapy"?"phone-strap-image":""} ${p.type==="Phone strapy crossbody"?"crossbody-image":""} ${p.type==="Bransoletki"?"bracelet-image":""} ${p.type==="Inne"?"other-image":""}`}><img src={p.src} alt={p.alt} loading="lazy"/><span className="project-id">{p.id}</span></div><div className="project-meta"><div><small>{"collection" in p?String(p.collection):p.type}</small><h3>{p.title}</h3><p>{p.note}</p></div><div className="color-dots" aria-label="Kolory projektu">{p.colors.map(c=><i key={c} style={{background:c}}/>)}</div></div></article>)}</div></div>
      {filter==="Breloki"&&visible.length>6&&<div className="show-more-wrap"><button className="show-more-button" type="button" onClick={()=>setShowAllKeyrings(value=>!value)} aria-expanded={showAllKeyrings}>{showAllKeyrings?"Pokaż mniej":"Pokaż więcej"} <span aria-hidden="true">{showAllKeyrings?"↑":"↓"}</span></button></div>}
    </section>

<section className="section products" id="produkty"><div className="section-top"><div><p className="index light">02 / CO TWORZĘ</p><h2>Nie katalog.<br/><em>Pole możliwości.</em></h2></div><div className="products-summary"><p className="section-intro">Oferta nie kończy się na obecnych formach. Każdy typ jest punktem wyjścia do rozmowy o kolorze, funkcji i detalu.</p><a className="btn btn-coral" href="#zamowienie">Zacznij projekt ↘</a></div></div><aside className="gift-ready"><div className="gift-ready-mark"><span>PAKOWANIE / 01</span><b>✦</b></div><div><p className="index">GOTOWE DO WRĘCZENIA</p><h3>Estetycznie zapakowane.<br/><em>Gotowe na prezent.</em></h3></div><div className="gift-ready-copy"><p>Każdy produkt pakuję starannie i estetycznie, tak aby od razu nadawał się na prezent - wystarczy wręczyć go bliskiej osobie albo sprawić przyjemność sobie.</p><div><span>ESTETYCZNE PAKOWANIE</span><span>GOTOWE NA PREZENT</span></div></div><div className="gift-gallery"><img src="/packaging/D5453026-74A0-492C-BC9A-501A265D6402.PNG" alt="Niebieska koperta ochronna z podziękowaniem" loading="lazy"/><img src="/packaging/D2D896F7-595F-4731-A0F0-D6792F1AB880.PNG" alt="Zestaw produktów przygotowany w pudełku prezentowym" loading="lazy"/><img src="/packaging/17338552-E772-4297-8906-898E718044A4.PNG" alt="Zapakowany prezent w pudełku z wakacyjnym papierem" loading="lazy"/></div></aside></section>

    <section className="section price-section" id="cennik"><div className="price-guide"><div className="price-guide-copy"><p className="index">CENNIK ORIENTACYJNY</p><h3>Każdy projekt<br/>ma własną <em>historię.</em></h3><p>Podane kwoty są orientacyjne. Dokładną cenę potwierdzę po ustaleniu szczegółów: kolorów, długości, splotu i dodatków.</p><p>Pozostałe produkty wyceniane są indywidualnie.</p></div><div><div className="price-list"><div><span>Brelok</span><strong>25–35 PLN</strong></div><div><span>Phone strap</span><strong>35–45 PLN</strong></div><div><span>Phone strap crossbody</span><strong>55–70 PLN</strong></div><div><span>Bransoletka</span><strong>20–25 PLN</strong></div><div><span>Sznurek do okularów</span><strong>18 PLN</strong></div><div><span>Uchwyt do maty</span><strong>65 PLN</strong></div><div><span>Adresówka dla pupila</span><strong>35 PLN</strong></div><div><span>Inne</span><strong>Wycena indywidualna</strong></div></div><p className="price-promo">Przy zamówieniu więcej niż 3 sztuk przewidziane są rabaty i gratisy. ✦</p></div></div></section>

    <section className="section colors" id="kolory">
      <div className="section-top">
        <div><p className="index">03 / KOLORY + DETALE</p><h2>Sznurki, zawieszki<br/><em>i małe detale.</em></h2></div>
        <p className="section-intro">Oferta stale się zmienia: pojawiają się nowe kolory, a niektóre warianty mogą być czasowo niedostępne. Poniżej znajdziesz aktualny katalog sznurków, uchwytów i zawieszek.</p>
      </div>
      <p className="swatch-note"><b>PRZYKŁADOWE PRÓBKI KOLORÓW</b> - odcień na ekranie może nieznacznie różnić się od rzeczywistego sznurka.</p>
      <div className="color-lab">
        <div className="swatches">{cordColors.map(([n,c])=><button type="button" key={n} className={chosenColors.includes(c)?"selected":""} onClick={()=>toggleColor(c)} aria-pressed={chosenColors.includes(c)}><span style={{background:c}}/><b>{n}</b><small>{chosenColors.includes(c)?"WYBRANO":"DODAJ"}</small></button>)}</div>
        <aside><p className="index">TWÓJ ZESTAW / SZKIC</p><div className="chosen-cords">{chosenColors.length?chosenColors.map(c=><i key={c} style={{background:c}}/>):<span>Wybierz próbki, żeby sprawdzić rytm kolorów.</span>}</div><p>To nie jest automatyczna wycena ani potwierdzenie dostępności. Wybór zostanie dołączony do zapytania.</p><a className="btn btn-dark" href="#zamowienie">Przejdź do zapytania ↘</a></aside>
      </div>
      <div className="component-catalog">
        <div className="catalog-heading">
          <div><p className="index">01 / SZNURKI</p><h3>Kolory sznurków</h3></div>
          <p>Trzy plansze pokazują aktualny katalog kolorów i wzorów. Wybrany kod możesz wpisać w formularzu zamówienia.</p>
        </div>
        <div className="cord-catalog-grid">
          <figure className="catalog-figure"><img src="/components/cords/kolory-1.png" alt="Katalog kolorów sznurków Surfcraftstories: czernie, granaty, błękity, szarość i biel" loading="lazy"/><figcaption>Kolory sznurków 1 / 3</figcaption></figure>
          <figure className="catalog-figure"><img src="/components/cords/kolory-2.png" alt="Katalog kolorów sznurków Surfcraftstories: czerwienie, pomarańcze i odcienie różu" loading="lazy"/><figcaption>Kolory sznurków 2 / 3</figcaption></figure>
          <figure className="catalog-figure"><img src="/components/cords/kolory-3.png" alt="Katalog kolorów sznurków Surfcraftstories: fiolety, zielenie, żółcie i beże" loading="lazy"/><figcaption>Kolory sznurków 3 / 3</figcaption></figure>
        </div>
      </div>
      <div className="component-catalog detail-catalog">
        <div className="catalog-heading">
          <div><p className="index">02 / KOMPONENTY</p><h3>Uchwyty i zawieszki</h3></div>
          <p>Kółka, karabińczyki, zawieszki, koraliki i literki pozwalają dopasować projekt do Twojego pomysłu.</p>
        </div>
        <div className="detail-catalog-grid">
          <figure className="catalog-figure"><img src="/components/details/uchwyty.png?v=2" alt="Dostępne rodzaje i kolory uchwytów, kółek oraz karabińczyków" loading="lazy"/><figcaption>Uchwyty i mocowania</figcaption></figure>
          <figure className="catalog-figure"><img src="/components/details/zawieszki.png?v=2" alt="Dostępne zawieszki, koraliki, literki i ozdobne detale" loading="lazy"/><figcaption>Zawieszki i ozdobne detale</figcaption></figure>
        </div>
      </div>
      <div className="component-note"><b>DOSTĘPNOŚĆ</b><p>Oferta sznurków i komponentów jest stale aktualizowana. Pojawiają się nowe warianty, a część może być czasowo niedostępna - wszystko potwierdzę przed rozpoczęciem pracy.</p><a href="#zamowienie">Zapytaj o swój zestaw ↘</a></div>
    </section>

<section className="section story" id="historia"><div className="story-head"><p className="index light">04 / HISTORIA</p><h2>Z zajawki.<br/>Z potrzeby <em>tworzenia.</em></h2></div><div className="chapters"><article><b>01 / ZAJAWKA</b><h3>Ruch daje kierunek.</h3><p>Surfskate był początkiem - nie jako gotowa estetyka, lecz źródło swobody, energii i odwagi do wyrażania własnego stylu.</p></article><article><b>02 / PIERWSZY SPLOT</b><h3>Materiał daje możliwości.</h3><p>Paracord pozwolił połączyć funkcję z mocnym kolorem. Z prostych linek zaczęły powstawać rzeczy codzienne, ale dalekie od anonimowych.</p></article><article><b>03 / KOLEJNE HISTORIE</b><h3>Projekt ciągle się rusza.</h3><p>Kolejne realizacje, zestawienia i próby układają się w Surfcraftstories - osobistą markę, która rośnie przez ciekawość i eksperymentowanie.</p></article></div><div className="about"><div className="about-visual"><figure className="about-photo about-photo-single"><img src="/about/about-surfskate-no-car.png" alt="Twórczyni Surfcraftstories na surfskate z własnoręcznie wykonanym phone strapem" loading="lazy"/><figcaption>TO JA / SURFSKATE / WŁASNA FALA</figcaption></figure><div className="about-stamp"><b>MADE BY HAND</b><span>W POLSCE · PO SWOJEMU</span></div></div><div className="about-copy"><p className="index">O MNIE</p><h3>Tworzę po swojemu.<br/><em>Na własnej fali.</em></h3><p>Surfcraftstories narodziło się z potrzeby tworzenia rzeczy po swojemu - intuicyjnie, kolorowo i bez oglądania się na gotowe schematy. Z tego wyjątkowego poczucia, że jesteś dokładnie tam, gdzie chcesz być: na właściwej fali.</p><p>Kocham wolność, ruch i tworzenie po swojemu. Surfskate daje mi energię, a wyplatanie pozwala zamknąć ją w rzeczach, które są jednocześnie praktyczne i osobiste.</p><p className="about-note">Każdy projekt tworzę ręcznie i po swojemu. Jeśli nie masz jeszcze konkretnego pomysłu, opowiedz mi trochę o sobie, o tym, co lubisz albo dla kogo ma powstać - wspólnie stworzymy coś, co będzie naprawdę Twoje.</p><div className="about-values" aria-label="Wartości Surfcraftstories"><span>WOLNOŚĆ</span><span>KOLOR</span><span>WAKACYJNY VIBE</span></div><p className="about-instagram">Chcesz śledzić moje surfskate’owe wyczyny? Zapraszam na Instagram <a href="https://www.instagram.com/brzozalina/" target="_blank" rel="noreferrer">@brzozalina ↗</a></p></div></div></section>

    <section className="section order" id="zamowienie"><div className="order-copy"><p className="index light">06 / ZAMÓWIENIE</p><h2>Masz pomysł?<br/><em>Zacznijmy rozmowę.</em></h2><p>Nie musisz znać nazwy splotu ani wybierać każdego detalu. Opisz potrzebę, pokaż inspirację albo po prostu wskaż kolory.</p><div className="mode-choice" role="group" aria-label="Sposób rozpoczęcia projektu">{["Mam konkretny pomysł","Potrzebuję pomocy w wyborze"].map(m=><button type="button" className={briefMode===m?"active":""} onClick={()=>setBriefMode(m)} key={m}>{m}</button>)}</div></div><form onSubmit={submit} noValidate={false}>{sent?<div className="success" role="status"><span>✓</span><h3>Dzięki! Pomysł jest zapisany.</h3><p>W lokalnej wersji formularz niczego jeszcze nie wysyła. Po podłączeniu obsługi zgłoszeń pojawi się tu ciepłe potwierdzenie i możliwość dalszego kontaktu.</p><button className="btn btn-dark" type="button" onClick={()=>setSent(false)}>Wyślij kolejne zapytanie</button></div>:<><input className="honey" name="website" tabIndex={-1} autoComplete="off" aria-hidden="true"/><input type="hidden" name="tryb" value={briefMode}/><input type="hidden" name="kolory" value={chosenColors.join(",")}/><div className="form-row"><label>Imię *<input required name="name" autoComplete="name" placeholder="Jak się do Ciebie zwracać?"/></label><label>E-mail *<input required type="email" name="email" autoComplete="email" placeholder="twoj@email.pl"/></label></div><div className="form-row"><label>Telefon - opcjonalnie<input type="tel" name="phone" autoComplete="tel"/></label><label>Instagram / sposób kontaktu<input name="contact" placeholder="np. @twojprofil"/></label></div><div className="form-row"><label>Typ produktu<select name="product" defaultValue=""><option value="">Jeszcze nie wiem</option><option>Brelok</option><option>Phone strap</option><option>Phone strap crossbody</option><option>Bransoletka</option><option>Smycz lub uchwyt</option><option>Inny pomysł</option></select></label><label>Orientacyjny rozmiar / długość<input name="size" placeholder="Jeśli już wiesz"/></label></div><label>Przeznaczenie produktu<input name="purpose" placeholder="Dla siebie, do telefonu, na prezent…"/></label><label>Opowiedz o pomyśle *<textarea required name="idea" rows={5} placeholder="Kolory, funkcja, klimat, detal, który jest dla Ciebie ważny…"/></label><div className="form-row"><label>Preferowany termin<input name="deadline" placeholder="Do ustalenia"/></label><label>Opcjonalny budżet<input name="budget" inputMode="decimal" placeholder="Jeśli chcesz podać"/></label></div><label className="file-label">Zdjęcie lub inspiracja - opcjonalnie<input type="file" name="inspiration" accept="image/*"/><span>Plik zostanie obsłużony po podłączeniu formularza.</span></label><label className="consent"><input required type="checkbox" name="consent"/> Zgadzam się na kontakt w sprawie mojego zapytania. Dane zostaną użyte wyłącznie do odpowiedzi. *</label><button className="btn btn-coral submit" type="submit">Wyślij swój pomysł <b>↗</b></button><p className="form-note">Wysłanie formularza rozpoczyna rozmowę - nie jest zamówieniem ani potwierdzeniem ceny i dostępności.</p></>}</form></section>

    <section className="section faq" id="faq"><div><p className="index">07 / FAQ</p><h2>Zanim<br/><em>napiszesz.</em></h2></div><div className="faq-list">{faqs.map(([q,a],i)=><details key={q}><summary><span>{String(i+1).padStart(2,"0")}</span>{q}<b>+</b></summary><p>{a}</p></details>)}</div></section>

    <footer><div><a className="footer-logo" href="#start"><img src="/surfcraftstories-logo.png" alt="Surfcraftstories"/></a><p>Ręcznie wyplatane. Po Twojemu.</p></div><div className="footer-nav"><a href="#realizacje">Realizacje</a><a href="#produkty">Co tworzę</a><a href="#historia">Historia</a><a href="#zamowienie">Kontakt</a></div><div className="footer-meta"><a className="instagram-more" href="https://www.instagram.com/surfcraftstories/" target="_blank" rel="noreferrer">Najnowsze realizacje i więcej znajdziesz na Instagramie <strong>@surfcraftstories</strong> ↗</a><a href="mailto:karolina_otreba@icloud.com">karolina_otreba@icloud.com</a><small>© 2026 SURFCRAFTSTORIES</small></div></footer>
    {gallery&&<div className="gallery-modal" role="dialog" aria-modal="true" aria-label={`Galeria produktu: ${gallery.title}`} onMouseDown={event=>{if(event.target===event.currentTarget)setGallery(null)}}><div className="gallery-dialog"><button className="gallery-close" type="button" onClick={()=>setGallery(null)} aria-label="Zamknij galerię">×</button><div className="gallery-dialog-image"><img src={gallery.items[gallery.active].src} alt={gallery.items[gallery.active].alt}/></div><div className="gallery-dialog-meta"><div><small>PHONE STRAP CROSSBODY · {gallery.active+1} / {gallery.items.length}</small><h3>{gallery.title}</h3></div><p>{gallery.items[gallery.active].note}</p></div><div className="gallery-modal-thumbnails">{gallery.items.map((item,index)=><button key={item.id} className={gallery.active===index?"active":""} type="button" onClick={()=>setGallery(current=>current?{...current,active:index}:current)} aria-label={`Pokaż zdjęcie ${index+1}`} aria-pressed={gallery.active===index}><img src={item.src} alt=""/></button>)}</div></div></div>}
  </main>
}
